<template><BioNexusDialog ref="dialog" size="standard" :kicker="mode==='create'?'Nuevo registro':'Editar registro'" :title="mode==='create'?'Crear antibi&oacute;tico':'Editar antibi&oacute;tico'" @close="reset"><section class="antibiotic-form"><BioNexusFormField label="Descripci&oacute;n" field-id="antibiotic-description" :error="descriptionError" :help="draft.description.length+' de 50 caracteres'" required><input id="antibiotic-description" ref="firstInput" v-model="draft.description" class="bio-nexus-field" @input="syncDirty" maxlength="50" autocomplete="off"></BioNexusFormField><BioNexusFormField label="Siglas" field-id="antibiotic-initials" :error="initialsError" :help="draft.siglas.length+' de 10 caracteres'" required><input id="antibiotic-initials" v-model="draft.siglas" class="bio-nexus-field" @input="syncDirty" maxlength="10" autocomplete="off"></BioNexusFormField><div v-if="errorMessage" class="bio-nexus-message bio-nexus-message-error">{{errorMessage}}</div></section><template #footer><button class="bio-nexus-action bio-nexus-action-secondary" :disabled="saving" @click="close">Cancelar</button><button class="bio-nexus-action bio-nexus-action-primary antibiotic-dialog-submit" :disabled="submitDisabled" @click="submit"><BioNexusActionIcon action="save"/>{{saving?'Guardando...':mode==='create'?'Crear':'Guardar'}}</button></template></BioNexusDialog></template>
<script setup>import{computed,nextTick,reactive,ref}from"vue";import BioNexusDialog from"@/components/ui/BioNexusDialog.vue";import BioNexusFormField from"@/components/ui/BioNexusFormField.vue";import BioNexusActionIcon from"@/components/ui/BioNexusActionIcon.vue";const props=defineProps({saving:Boolean,canCreate:Boolean,canUpdate:Boolean}),emit=defineEmits(["submit"]),dialog=ref(null),firstInput=ref(null),mode=ref("create"),current=ref(null),attempted=ref(false),errorMessage=ref(""),original=ref(""),dirty=ref(false),initializing=ref(false);const draft=reactive({description:"",siglas:""});const values=computed(()=>({description:draft.description.trim().toUpperCase(),siglas:draft.siglas.trim().toUpperCase()})),signature=computed(()=>JSON.stringify(values.value)),descriptionError=computed(()=>attempted.value&&!values.value.description?"La descripci\u00f3n es obligatoria.":""),initialsError=computed(()=>attempted.value&&!values.value.siglas?"Las siglas son obligatorias.":""),submitDisabled=computed(()=>initializing.value||props.saving||(mode.value==="create"?!props.canCreate:!props.canUpdate||!dirty.value));function snapshot(){return JSON.stringify(values.value)}function syncDirty(){dirty.value=!initializing.value&&snapshot()!==original.value}async function show(){await dialog.value?.open();await nextTick();original.value=snapshot();dirty.value=false;initializing.value=false;firstInput.value?.focus()}function assign(row){draft.description=row?.description||"";draft.siglas=row?.siglas||"";original.value=JSON.stringify(values.value)}async function openCreate(){initializing.value=true;mode.value="create";current.value=null;assign(null);attempted.value=false;errorMessage.value="";await show()}async function openEdit(row){initializing.value=true;mode.value="edit";current.value=row;assign(row);attempted.value=false;errorMessage.value="";await show()}function submit(){attempted.value=true;if(descriptionError.value||initialsError.value||submitDisabled.value)return;emit("submit",{mode:mode.value,record:current.value,values:values.value})}function close(){dialog.value?.close()}function reset(){attempted.value=false}function setError(value){errorMessage.value=String(value||"")}function clearError(){errorMessage.value=""}defineExpose({openCreate,openEdit,close,setError,clearError})</script>
<style scoped>.antibiotic-form{display:grid;grid-template-columns:minmax(0,2fr) minmax(150px,1fr);gap:var(--bio-nexus-space-3)}.bio-nexus-message{grid-column:1/-1}@media(max-width:620px){.antibiotic-form{grid-template-columns:1fr}}.antibiotic-dialog-submit:disabled{border-color:var(--bio-nexus-color-border)!important;background:var(--bio-nexus-color-surface-soft)!important;color:var(--bio-nexus-color-text-muted)!important;box-shadow:none!important;cursor:not-allowed!important;opacity:.58!important;pointer-events:none}</style>